def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.8
        return float(min(budget, base))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 2.5 * DAILY_SALARY:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid', 0.0)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = 1.0 - max(0.0, min(1.0, supply_ratio))

    survival_pressure = 0.0
    if hp <= 2:
        survival_pressure += 0.55
    elif hp <= 4:
        survival_pressure += 0.28
    if no_water_days >= 2:
        survival_pressure += 0.4
    elif no_water_days == 1:
        survival_pressure += 0.15

    market_pressure = 0.0
    if highest_prev >= 110:
        market_pressure = 0.55
    elif highest_prev >= 85:
        market_pressure = 0.4
    elif highest_prev >= 60:
        market_pressure = 0.25
    elif highest_prev >= 35:
        market_pressure = 0.12

    opp_pressure = min(0.2, urgent_opp * 0.06 + rich_opp * 0.03)

    base = DAILY_SALARY * (0.28 + 0.42 * scarcity + survival_pressure + market_pressure + opp_pressure)

    if prev_bids:
        if scarcity >= 0.55 or hp <= 3 or no_water_days >= 1:
            target = max(base, highest_prev + 2.0)
        else:
            target = max(base, avg_prev * 0.82 + 1.0)
    else:
        target = base

    if supply >= 23 and hp >= 5 and no_water_days == 0:
        target *= 0.72
    elif supply <= 17:
        target *= 1.18

    if day >= 8:
        target *= 1.08
    if day == 10:
        target *= 1.12

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if hp >= 4 and no_water_days == 0:
        reserve_floor = min(budget * 0.5, days_left * DAILY_SALARY * 0.22)

    bid = min(budget, target)
    if budget > reserve_floor:
        bid = min(bid, budget)
    bid = max(0.0, bid)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, highest_prev + 4.0 if highest_prev > 0 else DAILY_SALARY * 0.92))

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents alive, conserve.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate target bid level from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        median_prev_bid = sorted(yesterday_bids)[len(yesterday_bids)//2]
    else:
        highest_prev_bid = 0.0
        median_prev_bid = 0.0

    # Supply pressure: higher supply implies we can bid less.
    # Map supply into [0,1] where 0 at MIN_SUPPLY and 1 at MAX_SUPPLY.
    try:
        supply_norm = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    except Exception:
        supply_norm = 0.5
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Decide aggressiveness.
    # If I'm close to death or have already missed water, bid aggressively.
    # Otherwise, bid around the median/high band to beat typical survivors.
    if hp <= 2 or no_water_days >= 2:
        # Aggressive: try to outbid the highest observed.
        base = max(median_prev_bid, highest_prev_bid)
        # Add a small increment to likely win.
        target = base + 8.0
    elif hp <= 3:
        target = max(median_prev_bid, highest_prev_bid * 0.9) + 4.0
    else:
        # Conservative to preserve budget: bid near median, slightly above if supply is tighter.
        # When supply is low, increase bid.
        tighten = 1.0 - supply_norm
        target = max(median_prev_bid, 0.0) + 10.0 * tighten
        # If yesterday's highest was very high, we must respond.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, highest_prev_bid + 2.0)

    # Cap target by budget and a reasonable multiple of salary.
    # (Game likely pays/uses salary as a practical upper bound.)
    max_reasonable = DAILY_SALARY * 1.2
    target = min(target, max_reasonable)
    if budget < target:
        target = budget

    # Ensure non-negative.
    if target < 0.0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    day = int(day_context['day'])
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']

    # Base bid by day phase
    if day <= 3:
        base = 40
    elif day <= 6:
        base = 80
    else:
        base = 120

    # HP adjustment
    if hp <= 2:
        base = min(base + 30, DAILY_SALARY)
    elif hp <= 5:
        base += 10

    # Opponent yesterday max bid exploitation
    max_yesterday = 0
    for opp in opponents_status.values():
        prev = opp.get('previous_trace')
        if prev and prev.get('bid') is not None:
            max_yesterday = max(max_yesterday, prev['bid'])

    if max_yesterday > 0:
        target = max(base, max_yesterday + 2)
        if target > DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.9
        base = target

    bid = max(0.0, min(float(budget), float(base)))
    return bid
